"use strict";

const {
    test
  } = require('node:test'),
  assert = require('node:assert/strict'),
  S = require('../src/status.cjs');
test('phase contract distinguishes prompt preparation, provider work, returned-file saving and terminal outcomes', () => {
  assert.equal(S.describe({
    phase: 'preparing'
  }).label, '整理导演提示词');
  assert.equal(S.describe({
    phase: 'generating'
  }).label, '正在生成');
  assert.equal(S.describe({
    phase: 'saving'
  }).busy, true);
  for (const phase of ['done', 'failed', 'uncertain', 'cancelled']) assert.equal(S.describe({
    phase
  }).busy, false);
  assert.equal(S.fromRecord({
    status: 'generating',
    images: [{}]
  }).phase, 'generating');
  assert.equal(S.fromRecord({
    status: 'uncertain',
    images: [{}]
  }).phase, 'uncertain');
});
test('tracker cannot let an older completion hide another active task and can remove deleted-message work', () => {
  const t = S.createTracker();
  t.update('older', {
    phase: 'generating',
    messageId: '1'
  });
  t.update('newer', {
    phase: 'preparing',
    messageId: '2'
  });
  assert.equal(t.update('older', {
    phase: 'done'
  }).phase, 'preparing');
  t.update('newer', {
    phase: 'failed'
  });
  assert.equal(t.snapshot().phase, 'failed');
  t.update('third', {
    phase: 'generating',
    messageId: '3'
  });
  t.dropMessage('3');
  assert.equal(t.snapshot().phase, 'failed');
  t.reset();
  assert.equal(t.snapshot().phase, 'idle');
});
test('visible lifecycle labels are media neutral while keeping prompt and execution stages separate', () => {
  for (const phase of ['generating', 'saving', 'loading', 'done']) assert(!/图片|视频|动图/.test(S.describe({
    phase
  }).label));
  assert.equal(S.describe({
    phase: 'generating'
  }).label, '正在生成');
  assert.equal(S.describe({
    phase: 'saving'
  }).label, '正在保存');
  assert.notEqual(S.describe({
    phase: 'preparing'
  }).label, S.describe({
    phase: 'generating'
  }).label);
});
//# sourceMappingURL=data:application/json;charset=utf-8;base64,

test('a text turn without a queued director has an explicit non-image stage state', () => {
  const state = S.describe({ phase: 'no-director' });
  assert.equal(state.label, '未设置下一轮导演');
  assert.equal(state.busy, true);
  assert.match(state.hint, /不会自动生成画面/);
});
